structuredOutput:
{
  "summary": "Legion IDE Production Completion is an existing-product hardening program to turn a validated Rust IDE substrate into an evidence-backed, supportable production release. The next step is a human-approved production boundary and evidence rebaseline, followed by planning—not project initialization.",
  "proposals": [
    {
      "slot": "project.name",
      "value": "Legion IDE Production Completion",
      "rationale": "Matches the requested topic and the repository's active productionization mission.",
      "anchor": "problem-framing",
      "confidence": "researched"
    },
    {
      "slot": "project.entryPath",
      "value": "Existing project context",
      "rationale": "The repository already contains project state, a production master plan, readiness ledger, Kanban backlog, and evidence packages.",
      "anchor": "problem-framing",
      "confidence": "researched"
    },
    {
      "slot": "project.type",
      "value": "Production hardening and release-readiness program for an existing desktop IDE",
      "rationale": "The architecture is substantially implemented; remaining work concerns product workflows, honest gates, platform evidence, packaging, and explicit cut lines.",
      "anchor": "problem-framing",
      "confidence": "researched"
    },
    {
      "slot": "project.primaryOutcome",
      "value": "A daily-drivable, control-first Legion IDE whose Manual, Assist, Delegate, and Legion Workflow paths have current end-to-end evidence and whose unsupported surfaces are explicitly deferred.",
      "rationale": "This reflects HERMESGOAL.md and the production master plan's stated completion criteria.",
      "anchor": "recommended-next-action",
      "confidence": "researched"
    },
    {
      "slot": "project.targetUsers",
      "value": "Enterprise development teams needing local or self-hosted AI, auditability, policy controls, and low-latency native editing",
      "rationale": "This audience is explicitly named in the product-readiness ledger.",
      "anchor": "problem-framing",
      "confidence": "researched"
    },
    {
      "slot": "project.stack",
      "value": "Rust 2024 Cargo workspace with an eframe/egui desktop edge, app-owned composition, protocol DTOs, native editor/workspace services, LSP, PTY, Git, and gated AI/provider runtimes",
      "rationale": "This is the implemented repository architecture.",
      "anchor": "constraints",
      "confidence": "researched"
    },
    {
      "slot": "project.architectureConstraints",
      "value": "Projection-only UI; proposal-mediated mutation; metadata-only defaults; default-deny capability policy; opt-in hosted egress; fail-closed stale, conflict, scope, and evidence gates",
      "rationale": "These are standing architectural and security invariants across AGENTS.md and the readiness documents.",
      "anchor": "constraints",
      "confidence": "researched"
    },
    {
      "slot": "project.nonGoals",
      "value": "Autonomous main-workspace mutation, production claims based only on substrate tests, and presenting deferred or fixture-backed surfaces as operational",
      "rationale": "These behaviors are explicitly prohibited by current project policy.",
      "anchor": "constraints",
      "confidence": "researched"
    },
    {
      "slot": "project.executionStrategy",
      "value": "Balanced vertical-slice closeout: truth and behavioral gates, Manual daily-driver completion, real Assist and Delegate paths, language/debug completion, then packaging and release evidence",
      "rationale": "This preserves dependency order while prioritizing the smallest credible production path.",
      "anchor": "viable-approaches",
      "confidence": "inferred"
    }
  ],
  "openQuestions": [
    {
      "slot": "project.nextMilestone",
      "question": "Is the immediate target an external production beta under M12 cut lines, or full M13 GA readiness?",
      "why": "The two targets require different signing, platform, provider, extension, and enterprise evidence."
    },
    {
      "slot": "project.targetPlatforms",
      "question": "Should the first production claim be Windows-first, or require simultaneous Windows, macOS, and Linux readiness?",
      "why": "The project is Windows-first in places, while several readiness gates require current three-OS evidence."
    },
    {
      "slot": "project.signingAndUpdates",
      "question": "Are production signing credentials, native installers, and a hosted update feed available for this program?",
      "why": "Current evidence supports dry-run descriptors and unsigned portable previews; signed installers, fresh-VM proof, and production update infrastructure remain open."
    },
    {
      "slot": "project.extensionRuntimeScope",
      "question": "Must an approved VSIX execute in the target release, or should extension runtime remain explicitly deferred?",
      "why": "The beta acceptance scenario mentions installing a VSIX, but PR-VSC-002 and the current extension-host cut line defer runtime execution."
    },
    {
      "slot": "project.enterpriseSurfaceScope",
      "question": "Are remote development, collaboration, and enterprise administration required for this release or accepted as visible deferrals?",
      "why": "Their substrates exist, but PR-ENT-001 and PR-ENT-002 are explicitly deferred as product workflows."
    },
    {
      "slot": "project.liveAiProvider",
      "question": "Which local provider and hosted BYOK provider must pass the Assist golden path?",
      "why": "The default desktop path still has deterministic fixture behavior, while production utility calls for a real local and one hosted BYOK path."
    },
    {
      "slot": "project.sandboxPlatformPolicy",
      "question": "Must Delegate provide equivalent filesystem and network isolation on every target OS, or may weaker platforms carry an explicit preview restriction?",
      "why": "The documented Windows job-object boundary does not provide the same filesystem and network enforcement promised by stronger sandbox descriptions."
    },
    {
      "slot": "project.deliveryWindow",
      "question": "What deadline and risk tolerance govern the release boundary?",
      "why": "No approved schedule was found, and the answer determines whether deferred surfaces should be cut or completed."
    },
    {
      "slot": "project.baselineRef",
      "question": "Which local commit should be frozen as the production-completion baseline?",
      "why": "The local Legion status and map commands could not start in the read-only sandbox; repository state was therefore inspected through the GitHub default branch, while the checked-in planning map is stale."
    }
  ],
  "notes": [
    {
      "heading": "Problem Framing",
      "body": "The repository has two distinct completion concepts: .planning/ROADMAP.md reports Phases 1-13 complete, while README.md and plans/product-readiness-ledger.md explicitly say Legion is not GA. The roadmap proves architecture and substrate slices; production completion requires usable workflows, behavioral evidence, installability, supportability, and honest cut lines. The current Kanban contains 146 tasks: 107 done, 18 in progress, 20 todo, and 1 blocked."
    },
    {
      "heading": "Constraints",
      "body": "Do not weaken app-owned authority, projection-only UI, proposal-mediated saves and generated edits, metadata-only observability, or default-deny policy. Production claims must follow the readiness ledger rather than phase acceptance. The 21 standing gates remain necessary, but synthetic or report-only performance and benchmark outputs cannot alone establish product readiness. No files or external project state were changed during this exploration."
    },
    {
      "heading": "Open Questions",
      "body": "Human decisions are required for the release tier, platform matrix, signing and update infrastructure, VSIX runtime, enterprise surfaces, live AI providers, sandbox parity, schedule, and baseline commit. These choices materially alter scope and therefore should be resolved during intake instead of inferred."
    },
    {
      "heading": "Viable Approaches",
      "body": "Conservative: ship an explicitly unsigned production-preview focused on Manual Rust IDE workflows, with Assist, Delegate, extensions, and enterprise surfaces restricted or deferred; lowest risk but not GA. Balanced: close truth and behavioral gates, finish Manual daily driving, wire real Assist and bounded Delegate paths, complete critical language/debug workflows, then prove packaging and support while deferring remote, collaboration, and extension-host execution; recommended. Ambitious: complete all enterprise, extension-host, remote, collaboration, signing, updater, and cross-platform commitments before release; strongest promise but substantially larger and dependency-heavy."
    },
    {
      "heading": "Recommended Next Action",
      "body": "Run a production evidence rebaseline at an approved commit. Reconcile the completed phase roadmap against the readiness ledger, classify all 39 unfinished Kanban tasks as release blockers or accepted deferrals, replace synthetic evidence where it supports a production claim, and freeze one M12 or M13 acceptance matrix. The first implementation plan should then target the smallest failing vertical golden path rather than a broad crate-by-crate campaign."
    },
    {
      "heading": "Start Or Plan Handoff",
      "body": "Use a plan handoff, not a start handoff, because Legion IDE is already initialized. After the open decisions are answered, hand the approved brief to /legion:plan with HERMESGOAL.md, plans/product-readiness-ledger.md, plans/legion-production-master-plan-v0.2.md, plans/kanban/legion-ga-backlog.toml, AGENTS.md, and fresh legion status/map output as required inputs. No exploration artifact was recorded because this run was explicitly read-only."
    }
  ]
}
